-- 20261124b_catalogo_vehiculos (sesión 8, 24 nov 2026)
-- Q02/Q03: el catálogo tenía 26 combinaciones marca/tipo y ninguna moto: no se podía registrar
-- una motocicleta ni muchos autos comunes (p. ej., Honda solo tenía Accord y Civic).
-- Añade las marcas y modelos más conocidos a nivel internacional y en Bolivia, separados por tipo
-- (Automóvil, Camioneta, SUV, Vagoneta, Camión, Motocicleta), más:
--   * «Otro modelo (indícalo en la descripción)» en cada marca y tipo, y
--   * «Otra marca» en cada tipo,
-- para que el alta de un vehículo nunca quede bloqueada por un modelo que falta.
-- Solo AÑADE filas: no borra, no renombra ni desactiva nada. Idempotente (ON CONFLICT DO NOTHING).
-- 932 modelos, 75 marcas.

-- Tabla de trabajo que desaparece sola al terminar la transacción.
CREATE TEMP TABLE seed_catalogo_vehiculos (tipo text NOT NULL, marca text NOT NULL, modelos text[] NOT NULL) ON COMMIT DROP;


SELECT DISTINCT tipo FROM seed_catalogo_vehiculos
ON CONFLICT (nombre) DO NOTHING;

SELECT DISTINCT marca FROM seed_catalogo_vehiculos
ON CONFLICT (nombre) DO NOTHING;

SELECT ma.id, t.id, m.modelo
FROM seed_catalogo_vehiculos s
CROSS JOIN LATERAL unnest(s.modelos) AS m(modelo)
JOIN public.marcas ma ON ma.nombre = s.marca
JOIN public.tipos_vehiculo t ON t.nombre = s.tipo
ON CONFLICT (marca_id, tipo_vehiculo_id, nombre) DO NOTHING;
